const STYLE = {"Text": {"kind": "text", "size": 12, "weight": 400, "color": "#26364a"}, "mi": {"kind": "text", "size": 13, "weight": 600, "color": "#26364a"}, "brand": {"kind": "text", "size": 14, "weight": 800, "color": "#162234"}, "project": {"kind": "text", "size": 11, "weight": 400, "color": "#26364a"}, "logo": {"kind": "text", "size": 14, "weight": 400, "color": "#1f1f1f"}, "hbtn": {"kind": "box", "fill": "#ffffff", "stroke": "#d9d9d9", "radius": 6}, "recalc-all": {"kind": "box", "fill": "#ffffff", "stroke": "#d9d9d9", "radius": 6}, "next-btn": {"kind": "box", "fill": "#1a5276", "stroke": "#1a5276", "radius": 6}, "type-btn": {"kind": "box", "fill": "#ffffff", "stroke": "#d9d9d9", "radius": 6}, "mi-active": {"kind": "box", "fill": "#eef4ff", "stroke": "#c9d9ff", "radius": 6}, "mode-tag": {"kind": "box", "fill": "#eaf6ea", "stroke": "#b7dbb0", "radius": 6}, "thead": {"kind": "box", "fill": "#f4f7fa", "stroke": "#d1dce8", "radius": 0}, "trow": {"kind": "box", "fill": "#ffffff", "stroke": "#e0e7ef", "radius": 0}, "trow-empty": {"kind": "box", "fill": "#ffffff", "stroke": "#edf1f5", "radius": 0}, "div": {"kind": "box", "fill": "#dce5ee", "radius": 0}, "row-cb": {"kind": "box", "fill": "#ffffff", "stroke": "#d9d9d9", "radius": 2}};
const ROLES = {"section": {"size": 13.5, "weight": 600, "color": "#26364a"}, "muted": {"size": 11, "weight": 400, "color": "#7b8794"}, "th": {"size": 12, "weight": 600, "color": "#26364a"}, "modal-title": {"size": 13, "weight": 600, "color": "#26364a"}, "link": {"size": 12, "weight": 400, "color": "#2e86c1"}, "disabled": {"size": 12, "weight": 400, "color": "#b6bcc4"}, "field-label": {"size": 10.5, "weight": 600, "color": "#26364a"}, "panel-title": {"size": 10, "weight": 700, "color": "#4b5563"}};
const page = penpot.currentPage;
const cache = {};

// Приводим клон к эталону формы теплопотерь (heatcalc-shared.css).
function applyStyle(c, op) {
  const sp = STYLE[op.tpl];
  if (!sp) return;
  if (sp.kind === 'text' && c.type === 'text') {
    const role = (op.role && ROLES[op.role]) || {};
    c.fontSize = String(role.size !== undefined ? role.size : sp.size);
    c.fontWeight = String(role.weight !== undefined ? role.weight : sp.weight);
    const color = op.on_primary ? '#ffffff'
                : (op.fill || role.color || sp.color);
    c.fills = [{ fillColor: color, fillOpacity: 1 }];
    return;
  }
  if (sp.kind === 'box') {
    c.fills = [{ fillColor: op.fill || sp.fill, fillOpacity: 1 }];
    if (sp.stroke) {
      try {
        c.strokes = [{ strokeColor: sp.stroke, strokeOpacity: 1,
                       strokeWidth: 1, strokeStyle: 'solid',
                       strokeAlignment: 'inner' }];
      } catch (e) { /* шейп без обводки */ }
    } else {
      try { c.strokes = []; } catch (e) {}
    }
    if (sp.radius !== undefined) {
      try { c.borderRadius = sp.radius; } catch (e) {}
    }
  }
}

function tpl(name) {
  if (!(name in cache)) {
    const found = page.findShapes({ name: name }) || [];
    cache[name] = found.length ? found[0] : null;
  }
  return cache[name];
}

// идемпотентность: сносим прежние версии кадров с теми же именами
const wanted = {};
SPEC.frames.forEach(f => { wanted[f.name] = true; });
(SPEC.drop || []).forEach(n => { wanted[n] = true; });
Object.keys(wanted).forEach(name => {
  (page.findShapes({ name: name }) || []).forEach(s => { try { s.remove(); } catch (e) {} });
});

const missing = {};
let made = 0;

SPEC.frames.forEach(f => {
  const board = penpot.createBoard();
  board.name = f.name;
  board.x = f.x; board.y = f.y;
  board.resize(f.w, f.h);
  f.ops.forEach(op => {
    if (op.only === 'html') return;      // элемент только для HTML-носителя
    const t = tpl(op.tpl);
    if (!t) { missing[op.tpl] = true; return; }
    const c = t.clone();
    board.appendChild(c);
    c.x = f.x + op.x;
    c.y = f.y + op.y;
    if (op.w) c.resize(op.w, op.h || c.height);
    if (op.text !== null && op.text !== undefined && c.type === 'text') {
      c.characters = String(op.text);
    }
    applyStyle(c, op);
    if (op.opacity !== null && op.opacity !== undefined) c.opacity = op.opacity;
    made++;
  });
});

return { frames: SPEC.frames.length, shapes: made, missingTemplates: Object.keys(missing) };
